/**
 * Basma AI Chat Agent — Cloudflare AIChatAgent + ai SDK
 * BrainSAIT BSMA v5.0
 *
 * Architecture:
 *   Core: AIChatAgent (persistent SQLite, streaming, auto-resume)
 *   AI: DeepSeek via ai SDK streamText + custom DeepSeek provider
 *   Tools: Eligibility, Appointments, Network KPIs, Patient Lookup
 *   Voice: Client-side Web Speech API (STT) + ElevenLabs REST (TTS)
 *   Client: Vanilla JS (no React dependency needed)
 *
 * Features:
 *   - Automatic message persistence in SQLite
 *   - Resumable streaming (disconnect/reconnect mid-stream)
 *   - Real-time WebSocket sync to all clients
 *   - Tool calling with server-side execution
 *   - Bilingual Arabic (Saudi dialect) + English
 *   - 6-hospital Oracle Bridge integration
 *   - Emergency detection before AI call
 */

import { AIChatAgent, type AIChatAgentOptions } from "@cloudflare/ai-chat";
import { routeAgentRequest } from "agents";
import { streamText } from "ai";
import { createDeepSeek } from "./deepseek-provider";

// ─── Env ──────────────────────────────────────────────────────────────────────

export interface Env {
  AI: Ai;
  ASSETS: Fetcher;
  BasmaChatAgent: DurableObjectNamespace;
  DEEPSEEK_API_KEY: string;
  ELEVENLABS_API_KEY: string;
  ORACLE_BRIDGE_URL: string;
  ORACLE_BRIDGE_KEY: string;
  CLAIMLINC_API_KEY: string;
  CLAIMLINC_URL: string;
  NPHIES_MIRROR_URL: string;
  HEALTHCARE_DB: D1Database;
}

// ─── System Prompts ──────────────────────────────────────────────────────────

const SYSTEM_PROMPT_AR = `أنت بسمة، مساعدة BrainSAIT الصحية الذكية. تتحدثين باللهجة السعودية (ريدي/نجدي).

شخصيتك:
- دافئة، مهنية، واضحة — دكتورة صديقة
- تستخدمين تعابير سعودية مثل: "حيّاك الله"، "الله يسلمك"، "إن شاء الله"، "طيب"، "تمام"
- لا تستخدمين الفصحى أو العربية الرسمية

مهامك المتاحة:
1. التحقق من أهلية التأمين — اسألي عن رقم الهوية الوطنية (10 أرقام) أو الإقامة
2. معلومات المواعيد القادمة — اسألي عن رقم الملف الطبي (MRN)
3. إحصائيات الشبكة — القيمة الإجمالية، نسبة الموافقة، عدد المطالبات
4. البحث عن مريض — الاسم أو رقم الهوية

قواعد مهمة:
- في حالة الطوارئ (ألم صدر، ضيق تنفس، نزيف، فاقد وعي) → أرسلي فوراً للطوارئ
- لا تذكري أنك مساعد ذكاء اصطناعي، قولي "أنا بسمة"
- لا تخلطي الإنجليزية مع العربية
- إذا طلب المستخدم شيء خارج نطاقك، حوليه للفريق الطبي مباشرة`;

const SYSTEM_PROMPT_EN = `You are Basma, BrainSAIT's intelligent healthcare assistant.

Personality:
- Warm, professional, clear — like a trusted nurse who knows her stuff
- Natural and conversational, not robotic
- Never mention you're an AI — say "I'm Basma"

Available tools:
1. Insurance Eligibility — ask for national ID (10 digits)
2. Appointment Information — ask for MRN (medical record number)
3. Network Statistics — total value, approval rate, claim counts
4. Patient Lookup — by name or national ID

Rules:
- EMERGENCY (chest pain, severe bleeding, unconscious, stroke) → immediately tell them to go to ER
- Never mix languages
- If asked something outside your scope, direct them to the medical team`;

// ─── Emergency keywords ──────────────────────────────────────────────────────

const EMERGENCY_WORDS = [
  "chest pain", "heart attack", "shortness of breath", "can't breathe",
  "heavy bleeding", "unconscious", "stroke", "seizure",
  "نزيف", "طوارئ", "حالة حرجة", "فاقد الوعي",
  "جلطة", "نوبة", "ألم صدر", "ضيق تنفس",
];

// ─── Chat Agent ──────────────────────────────────────────────────────────────

export class BasmaChatAgent extends AIChatAgent<Env> {
  /** Keep 100 most recent messages */
  maxPersistedMessages = 100;

  /** Queue messages for orderly processing */
  messageConcurrency = "queue" as const;

  async onChatMessage(
    onFinish?: () => void,
    options?: AIChatAgentOptions
  ) {
    const message = this.messages[this.messages.length - 1];
    const text = typeof message === "string" ? message : message?.content || "";
    const isArabic = /[\u0600-\u06FF]/.test(text);

    // ── Emergency check ──────────────────────────────────────────────
    const lower = text.toLowerCase();
    if (EMERGENCY_WORDS.some((w) => lower.includes(w))) {
      return new Response(
        isArabic
          ? "🚨 هذه حالة طارئة! يجب التوجه فوراً إلى أقرب طوارئ أو الاتصال بالطوارئ (997). أرسل موقعك وأرسل لك المساعدة."
          : "🚨 This is an emergency! Go to the nearest ER immediately or call 997.",
        { headers: { "Content-Type": "text/plain; charset=utf-8" } }
      );
    }

    // ── Tool detection: eligibility check ────────────────────────────
    const idMatch = text.match(/\b(\d{10})\b/);
    if (idMatch && /أهلية|تأمين|تغطية|eligibility|insurance/i.test(text)) {
      try {
        const result = await checkEligibility(
          this.env,
          idMatch[1],
          (options?.body as Record<string, unknown>)?.hospital as string || "riyadh"
        );
        return new Response(result, {
          headers: { "Content-Type": "text/plain; charset=utf-8" },
        });
      } catch {
        // Fall through to DeepSeek
      }
    }

    // ── Stream from DeepSeek ─────────────────────────────────────────
    const deepseek = createDeepSeek({ apiKey: this.env.DEEPSEEK_API_KEY });

    const result = streamText({
      model: deepseek("deepseek-chat"),
      system: isArabic ? SYSTEM_PROMPT_AR : SYSTEM_PROMPT_EN,
      messages: this.messages.map(m => ({ role: m.role, content: m.content })),
      maxRetries: 1,
      // Tool definitions — the agent will decide when to use them
      tools: {
        checkEligibility: {
          description: "Check patient insurance eligibility by national ID or iqama number",
          parameters: {
            type: "object",
            properties: {
              identifier: { type: "string", description: "National ID (10 digits) or iqama number" },
              hospital: { type: "string", description: "Hospital branch: riyadh, madinah, unaizah, khamis, jizan, abha", default: "riyadh" },
            },
            required: ["identifier"],
          },
          execute: async ({ identifier, hospital }) => {
            return await checkEligibility(this.env, identifier, hospital || "riyadh");
          },
        },
        getAppointments: {
          description: "Get upcoming appointments for a patient by MRN and hospital",
          parameters: {
            type: "object",
            properties: {
              mrn: { type: "string", description: "Medical Record Number" },
              hospital: { type: "string", description: "Hospital branch", default: "riyadh" },
            },
            required: ["mrn"],
          },
          execute: async ({ mrn, hospital }) => {
            return await getAppointments(this.env, mrn, hospital || "riyadh");
          },
        },
        getNetworkKPIs: {
          description: "Get NPHIES network statistics — total value, approval rate, claim counts",
          parameters: {
            type: "object",
            properties: {
              hospital: { type: "string", description: "Hospital branch for hospital-specific data (optional)" },
            },
          },
          execute: async () => {
            return await getNetworkKPIs(this.env);
          },
        },
        patientLookup: {
          description: "Look up a patient by name or national ID through Oracle Bridge",
          parameters: {
            type: "object",
            properties: {
              query: { type: "string", description: "Patient name or national ID" },
              hospital: { type: "string", description: "Hospital branch", default: "riyadh" },
            },
            required: ["query"],
          },
          execute: async ({ query, hospital }) => {
            return await patientLookup(this.env, query, hospital || "riyadh");
          },
        },
      } as const,
      maxSteps: 5, // Allow up to 5 tool-calling turns
    });

    return result.toTextStreamResponse();
  }
}

// ─── Tool Implementations ────────────────────────────────────────────────────

async function checkEligibility(env: Env, identifier: string, hospital: string): Promise<string> {
  const isArabic = /[\u0600-\u06FF]/.test(identifier) === false; // heuristic
  try {
    const url = new URL(`${env.CLAIMLINC_URL}/nphies/eligibility/${hospital}`);
    url.searchParams.set("identifier", identifier);
    url.searchParams.set("type", "NATIONAL NUMBER");

    const resp = await fetch(url.toString(), {
      headers: { "X-API-Key": env.CLAIMLINC_API_KEY },
      signal: AbortSignal.timeout(10000),
    });

    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data = (await resp.json()) as Record<string, unknown>;
    const eligible = Boolean(data.eligible ?? data.isEligible ?? false);

    return eligible
      ? (isArabic
          ? `✅ الأهلية مؤكدة. التغطية التأمينية نشطة.`
          : `✅ Eligibility confirmed. Insurance coverage is active.`)
      : (isArabic
          ? `❌ عذراً، لا توجد تغطية تأمينية نشطة لهذه الهوية.`
          : `❌ No active insurance coverage found for this ID.`);
  } catch (e) {
    return isArabic
      ? `تعذّر التحقق من الأهلية حالياً. حاول مرة أخرى لاحقاً.`
      : `Unable to check eligibility right now. Please try again later.`;
  }
}

async function getAppointments(env: Env, mrn: string, hospital: string): Promise<string> {
  try {
    const resp = await fetch(
      `${env.ORACLE_BRIDGE_URL}/appointments?mrn=${encodeURIComponent(mrn)}&hospital=${hospital}`,
      {
        headers: { "X-API-Key": env.ORACLE_BRIDGE_KEY },
        signal: AbortSignal.timeout(10000),
      }
    );

    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data = (await resp.json()) as Record<string, unknown>;

    const appointments = (data.appointments || data.data || data) as Array<Record<string, unknown>>;
    if (!Array.isArray(appointments) || appointments.length === 0) {
      return `لا توجد مواعيد قادمة.`;
    }

    const list = appointments.slice(0, 5).map((a: Record<string, unknown>, i: number) =>
      `${i + 1}. ${a.date || a.appointment_date || "-"} — ${a.department || a.clinic || a.specialty || "-"}`
    ).join("\n");

    return `المواعيد القادمة:\n${list}`;
  } catch (e) {
    return `تعذّر جلب المواعيد: ${(e as Error).message}`;
  }
}

async function getNetworkKPIs(env: Env): Promise<string> {
  try {
    const resp = await fetch(`${env.CLAIMLINC_URL}/nphies/network/summary`, {
      headers: { "X-API-Key": env.CLAIMLINC_API_KEY },
      signal: AbortSignal.timeout(5000),
    });

    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const raw = (await resp.json()) as Record<string, unknown>;

    const tv = Number(raw.total_network_value || 0);
    const ar = Number(raw.approval_rate || 0);
    const gss = Number(raw.gss_count || 0);
    const pa = Number(raw.pa_count || 0);

    return [
      `📊 إحصائيات شبكة NPHIES:`,
      `• القيمة الإجمالية: ${(tv / 1_000_000).toFixed(1)} مليون ريال`,
      `• نسبة الموافقة: ${ar}%`,
      `• عدد المطالبات: ${gss.toLocaleString("en")}`,
      `• الموافقات المسبقة: ${pa.toLocaleString("en")}`,
    ].join("\n");
  } catch (e) {
    return `تعذّر جلب الإحصائيات: ${(e as Error).message}`;
  }
}

async function patientLookup(env: Env, query: string, hospital: string): Promise<string> {
  try {
    const resp = await fetch(
      `${env.ORACLE_BRIDGE_URL}/patient/search?hospital=${hospital}&name=${encodeURIComponent(query)}`,
      {
        headers: { "X-API-Key": env.ORACLE_BRIDGE_KEY },
        signal: AbortSignal.timeout(10000),
      }
    );

    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);

    const data = (await resp.json()) as { patients?: Array<{ name?: string; mrn?: string; national_id?: string }> };
    const patients = data.patients || [];
    if (patients.length === 0) return "لم يتم العثور على مريض بهذه البيانات.";

    const p = patients[0];
    return `تم العثور على: ${p.name || "غير معروف"}.\nرقم الملف: ${p.mrn || "-"}\nرقم الهوية: ${p.national_id || "-"}`;
  } catch (e) {
    return `تعذّر البحث: ${(e as Error).message}`;
  }
}

// ─── DeepSeek Provider ───────────────────────────────────────────────────────

import { createDeepSeek } from "./deepseek-provider";

// ─── fetch handler ───────────────────────────────────────────────────────────

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext) {
    const url = new URL(request.url);
    const corsHeaders = {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, X-Session-ID, X-Hospital",
    };

    if (request.method === "OPTIONS") {
      return new Response(null, { headers: { ...corsHeaders, "Content-Type": "application/json" } });
    }

    // Health
    if (url.pathname === "/health" || url.pathname === "/basma/status") {
      return Response.json(
        {
          status: "ok",
          agent: "basma-chat-v5",
          version: "5.0.0",
          deepseek: !!env.DEEPSEEK_API_KEY,
          oracle: !!env.ORACLE_BRIDGE_URL && !!env.ORACLE_BRIDGE_KEY,
          claimlinc: !!env.CLAIMLINC_URL && !!env.CLAIMLINC_API_KEY,
          timestamp: new Date().toISOString(),
        },
        { headers: corsHeaders }
      );
    }

    // ── Chat endpoint ─────────────────────────────────────────────────
    if (url.pathname === "/basma/chat" && request.method === "POST") {
      try {
        const body = (await request.json()) as {
          message?: string;
          lang?: string;
          hospital?: string;
        };
        const message = body.message || "";
        const isArabic = body.lang === "ar" || /[\u0600-\u06FF]/.test(message);

        // Emergency check
        const lower = message.toLowerCase();
        if (EMERGENCY_WORDS.some((w) => lower.includes(w))) {
          return new Response(
            JSON.stringify({
              response: isArabic
                ? "🚨 هذه حالة طارئة! توجه فوراً إلى أقرب طوارئ أو اتصل بالطوارئ (997)."
                : "🚨 Emergency! Go to the nearest ER immediately or call 997."
            }),
            { headers: { ...corsHeaders, "Content-Type": "application/json" } }
          );
        }

        // Direct tool check: eligibility by 10-digit ID
        const idMatch = message.match(/\b(\d{10})\b/);
        if (idMatch && /أهلية|تأمين|تغطية|eligibility|insurance/i.test(message)) {
          const result = await checkEligibility(env, idMatch[1], body.hospital || "riyadh");
          return new Response(
            JSON.stringify({ response: result }),
            { headers: { ...corsHeaders, "Content-Type": "application/json" } }
          );
        }

        // Call DeepSeek directly
        const deepseek = createDeepSeek({ apiKey: env.DEEPSEEK_API_KEY });
        const result = streamText({
          model: deepseek("deepseek-chat"),
          system: isArabic ? SYSTEM_PROMPT_AR : SYSTEM_PROMPT_EN,
          messages: [{ role: "user", content: message }],
          tools: {
            checkEligibility: {
              description: "Check patient insurance eligibility by national ID",
              parameters: { type: "object", properties: { identifier: { type: "string" }, hospital: { type: "string" } }, required: ["identifier"] },
              execute: async ({ identifier, hospital }: { identifier: string; hospital?: string }) => {
                return await checkEligibility(env, identifier, hospital || "riyadh");
              },
            },
            getAppointments: {
              description: "Get upcoming appointments by MRN",
              parameters: { type: "object", properties: { mrn: { type: "string" }, hospital: { type: "string" } }, required: ["mrn"] },
              execute: async ({ mrn, hospital }: { mrn: string; hospital?: string }) => {
                return await getAppointments(env, mrn, hospital || "riyadh");
              },
            },
            getNetworkKPIs: {
              description: "Get NPHIES network statistics",
              parameters: { type: "object", properties: {} },
              execute: async () => {
                return await getNetworkKPIs(env);
              },
            },
          },
        });

        // Collect the full streaming response
        let fullText = "";
        for await (const chunk of result.textStream) {
          fullText += chunk;
        }

        return new Response(
          JSON.stringify({ response: fullText }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      } catch (err) {
        return new Response(
          JSON.stringify({ response: "", error: (err as Error).message }),
          { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
    }

    // Static assets
    const staticPaths = ["/", "/index.html", "/basma-voice-client.js"];
    if (staticPaths.includes(url.pathname)) {
      try {
        const asset = await env.ASSETS.fetch(request);
        if (asset.status !== 404) {
          const text = await asset.text();
          const ct = url.pathname.endsWith(".js") ? "application/javascript" : "text/html; charset=utf-8";
          return new Response(text, { headers: { "Content-Type": ct, ...corsHeaders } });
        }
      } catch {}
    }

    // Try any static asset
    try {
      const result = await env.ASSETS.fetch(request);
      if (result.status !== 404) return result;
    } catch {}

    // Route to Chat Agent Durable Object
    return (await routeAgentRequest(request, env)) ||
      Response.json({ error: "Not found" }, { status: 404, headers: corsHeaders });
  },
} satisfies ExportedHandler<Env>;
