/**
 * DeepSeek LanguageModel provider for the `ai` SDK (v6.x)
 *
 * Implements the `LanguageModel` interface needed by `streamText`:
 *   - provider name: "deepseek"
 *   - modelId: "deepseek-chat"
 *   - doStream(): returns ReadableStream of AI SDK chunks
 */

import type { LanguageModelV1, LanguageModelV1StreamPart } from "ai";

export function createDeepSeek(options: { apiKey: string }) {
  const { apiKey } = options;

  return (modelId: string): LanguageModelV1 => {
    return {
      specificationVersion: "v1",
      provider: "deepseek",
      modelId,

      defaultObjectGenerationMode: undefined,

      // Text streaming — used by streamText()
      async doStream({
        inputFormat,
        prompt,
        mode,
        abortSignal,
      }: {
        inputFormat: "messages" | "prompt";
        prompt: Array<unknown>;
        mode: { type: "regular" | "object-json" | "object-tool" | "tool-call" };
        abortSignal?: AbortSignal;
      }) {
        // Build DeepSeek API body from the SDK messages
        const messages: Array<{ role: string; content: string }> = [];
        let systemMessage: string | undefined;

        for (const msg of prompt as Array<{ role: string; content: string; system?: string }>) {
          if (msg.role === "system") {
            systemMessage = msg.content;
            continue;
          }
          if (typeof msg.content === "string") {
            messages.push({ role: msg.role, content: msg.content });
          }
        }

        const body: Record<string, unknown> = {
          model: modelId,
          messages,
          stream: true,
          max_tokens: 4096,
          temperature: 0.7,
        };

        if (systemMessage) {
          body.messages = [{ role: "system", content: systemMessage }, ...messages];
        }

        // Call DeepSeek API
        const response = await fetch("https://api.deepseek.com/v1/chat/completions", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${apiKey}`,
          },
          body: JSON.stringify(body),
          signal: abortSignal || AbortSignal.timeout(20000),
        });

        if (!response.ok) {
          const errText = await response.text();
          throw new Error(`DeepSeek ${response.status}: ${errText}`);
        }

        // Convert DeepSeek SSE stream to AI SDK chunks
        const reader = response.body!.getReader();
        const decoder = new TextDecoder();
        let buffer = "";

        const stream = new ReadableStream<LanguageModelV1StreamPart>({
          async pull(controller) {
            while (true) {
              const { done, value } = await reader.read();
              if (done) {
                // Flush remaining buffer
                if (buffer.trim()) processLine(buffer.trim(), controller);
                controller.close();
                return;
              }

              buffer += decoder.decode(value, { stream: true });
              const lines = buffer.split("\n");
              buffer = lines.pop() || "";

              for (const line of lines) {
                const trimmed = line.trim();
                if (trimmed.startsWith("data: ")) {
                  const data = trimmed.slice(6);
                  if (data === "[DONE]") continue;
                  processData(data, controller);
                }
              }
            }
          },
        });

        return {
          stream,
          rawCall: { rawPrompt: prompt, rawSettings: {} },
        };
      },

      // Not used by streamText for text, but needed for conformance
      async doGenerate(opts) {
        // Fallback: use doStream and collect all chunks
        const { stream } = await this.doStream(opts);
        const reader = stream.getReader();
        let fullText = "";
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          if (value.type === "text-delta") {
            fullText += value.textDelta;
          }
        }
        return {
          text: fullText,
          finishReason: "stop" as const,
          usage: { promptTokens: 0, completionTokens: 0 },
          rawCall: { rawPrompt: opts.prompt, rawSettings: {} },
        };
      },
    };
  };
}

// ─── SSE parsing helpers ──────────────────────────────────────────────

function processData(data: string, controller: ReadableStreamDefaultController<LanguageModelV1StreamPart>) {
  try {
    const parsed = JSON.parse(data);
    const delta = parsed.choices?.[0]?.delta;
    if (!delta) return;

    // Text content
    if (delta.content) {
      controller.enqueue({
        type: "text-delta",
        textDelta: delta.content,
      });
    }

    // Tool calls
    if (delta.tool_calls) {
      for (const tc of delta.tool_calls) {
        controller.enqueue({
          type: "tool-call-delta",
          toolCallId: tc.id || `tc_${Date.now()}`,
          toolCallType: "function",
          argsTextDelta: tc.function?.arguments || "",
        });
      }
    }

    // Finish reason
    const finish = parsed.choices?.[0]?.finish_reason;
    if (finish) {
      controller.enqueue({
        type: "finish",
        finishReason: finish === "stop" ? "stop" : finish === "length" ? "length" : "other",
        usage: {
          promptTokens: parsed.usage?.prompt_tokens || 0,
          completionTokens: parsed.usage?.completion_tokens || 0,
        },
      });
    }
  } catch {
    // Skip malformed chunks
  }
}

function processLine(line: string, controller: ReadableStreamDefaultController<LanguageModelV1StreamPart>) {
  if (line.startsWith("data: ")) {
    processData(line.slice(6), controller);
  }
}
